\title{Death Avoidance as the Dominant Routing Signal:\\A Counterfactual Analysis on ScienceWorld}

\author{Anonymous}

\begin{document}
\maketitle

\input{abstract}
\input{introduction}
\input{method}
\input{experiments}
\input{related_work}
